  ('ancestry.gnome', 'Gnomo', 'Gnome', 'Gnomo', 'Ancestralidade pequena ligada à curiosidade, magia e experiências intensas.', 'A Small ancestry tied to curiosity, magic, and vivid experiences.', 'Una ascendencia Pequeña vinculada a la curiosidad, la magia y experiencias intensas.', 8, 'Pequeno', 25, '"Constituição","Carisma","Livre"'::text[], 'Força', '"Comum","Gnomo","Silvestre"'::text[], '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 50, '{"senses":["Visão na Penumbra"],"heritagesList":["Gnomo Camaleão","Gnomo Feérico","Gnomo Sensitivo","Gnomo do Umbral","Gnomo Poço de Vigor"],"needs_review":false}'::jsonb),
