  ('item.compendium.ten_foot_pole', 'Vara de 3 Metros', 'Ten-foot Pole', 'Pértiga de 3 metros', 'Vara de madeira rígida de 3 metros para testar pisos e desarmar armadilhas.', 'A rigid 3-meter wooden pole for testing floors and triggering traps from a distance.', 'Una vara rígida de madera de 3 metros para probar suelos y activar trampas a distancia.', 'Gear', 0, '1 CP', 1, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
