  ('item.compendium.writing_set', 'Conjunto de Escrita', 'Writing Set', 'Juego de escritura', 'Pena, tinta nanquim, pergaminhos e cera para selagem de cartas.', 'A quill, ink, parchment, and sealing wax for writing and sealing letters.', 'Una pluma, tinta, pergamino y cera de sellado para escribir y cerrar cartas.', 'Gear', 0, '1 GP', 0, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.elixir_of_life_minor', 'Elixir da Vida (Menor)', 'Elixir of Life (Minor)', 'Elixir de vida (menor)', 'Ao beber, recupera 1d6 Pontos de Vida e concede +1 de bônus de item em testes de Fortitude contra venenos e doenças por 1 hora.', 'When consumed, you regain 1d6 Hit Points and gain a +1 item bonus to Fortitude saves against poisons and diseases for 1 hour.', 'Al beberlo, recuperas 1d6 Puntos de Golpe y obtienes un bonificador de objeto +1 a las salvaciones de Fortaleza contra venenos y enfermedades durante 1 hora.', 'Consumables', 1, '3 GP', 0, '"Alquímico","Elixir","Cura"'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.elixir_of_life_lesser', 'Elixir da Vida (Inferior)', 'Elixir of Life (Lesser)', 'Elixir de vida (menor potente)', 'Ao beber, recupera 3d6+6 Pontos de Vida e concede +1 de bônus de item em testes contra venenos e doenças.', 'When consumed, you regain 3d6+6 Hit Points and gain a +1 item bonus to saves against poisons and diseases.', 'Al beberlo, recuperas 3d6+6 Puntos de Golpe y obtienes un bonificador de objeto +1 a las salvaciones contra venenos y enfermedades.', 'Consumables', 5, '12 GP', 0, '"Alquímico","Elixir","Cura"'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.healing_potion_minor', 'Poção de Cura (Menor)', 'Healing Potion (Minor)', 'Poción de curación (menor)', 'Poção mágica efervescente de coloração rubi que cura instantaneamente 1d8 Pontos de Vida.', 'An effervescent ruby-colored magic potion that immediately restores 1d8 Hit Points.', 'Una poción mágica efervescente de color rubí que restaura inmediatamente 1d8 Puntos de Golpe.', 'Consumables', 1, '4 GP', 0, '"Mágico","Poção","Cura"'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.healing_potion_lesser', 'Poção de Cura (Inferior)', 'Healing Potion (Lesser)', 'Poción de curación (menor potente)', 'Poção mágica potente que cura instantaneamente 2d8+5 Pontos de Vida.', 'A potent magic potion that immediately restores 2d8+5 Hit Points.', 'Una potente poción mágica que restaura inmediatamente 2d8+5 Puntos de Golpe.', 'Consumables', 3, '12 GP', 0, '"Mágico","Poção","Cura"'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.alchemist_s_fire_lesser', 'Fogo Alquímico (Inferior)', 'Alchemist''s Fire (Lesser)', 'Fuego alquímico (menor)', 'Frasco volátil que causa 1d8 de dano de fogo no impacto, 1 de dano de fogo contínuo e 1 de dano de fogo em respingo.', 'A volatile flask dealing 1d8 fire damage on impact, 1 persistent fire damage, and 1 splash fire damage.', 'Un frasco volátil que causa 1d8 de daño de fuego al impactar, 1 de daño de fuego persistente y 1 de daño de fuego por salpicadura.', 'Consumables', 1, '3 GP', 0, '"Alquímico","Bomba","Fogo"'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.acid_flask_lesser', 'Frasco de Ácido (Inferior)', 'Acid Flask (Lesser)', 'Frasco de ácido (menor)', 'Causa 1 de dano de ácido, 1d6 de dano de ácido contínuo e 1 de dano de ácido em respingo.', 'It deals 1 acid damage, 1d6 persistent acid damage, and 1 splash acid damage.', 'Inflige 1 de daño de ácido, 1d6 de daño de ácido persistente y 1 de daño de ácido por salpicadura.', 'Consumables', 1, '3 GP', 0, '"Alquímico","Bomba","Ácido"'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.frost_vial_lesser', 'Vial de Frio (Inferior)', 'Frost Vial (Lesser)', 'Vial de escarcha (menor)', 'Causa 1d6 de dano de frio, 1 de respingo e aplica penalidade de -3m no deslocamento da vítima.', 'It deals 1d6 cold damage, 1 splash damage, and gives the victim a –3-meter penalty to Speed.', 'Inflige 1d6 de daño de frío, 1 de salpicadura y aplica una penalización de –3 metros a la Velocidad de la víctima.', 'Consumables', 1, '3 GP', 0, '"Alquímico","Bomba","Frio"'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.bottled_lightning_lesser', 'Relâmpago Engarrafado (Inferior)', 'Bottled Lightning (Lesser)', 'Rayo embotellado (menor)', 'Causa 1d6 de dano elétrico, 1 de respingo e deixa o alvo Desprevenido até o início do próximo turno.', 'It deals 1d6 electricity damage, 1 splash damage, and leaves the target off-guard until the start of its next turn.', 'Inflige 1d6 de daño eléctrico, 1 de salpicadura y deja al objetivo desprevenido hasta el inicio de su próximo turno.', 'Consumables', 1, '3 GP', 0, '"Alquímico","Bomba","Eletricidade"'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.tanglefoot_bag_lesser', 'Bolsa de Resina (Inferior)', 'Tanglefoot Bag (Lesser)', 'Bolsa de enredadera (menor)', 'Bolsa de resina expansiva que gruda nas pernas do alvo, reduzindo a velocidade em 3m ou imobilizando no acerto crítico.', 'An expanding resin bag that sticks to the target''s legs, reducing Speed by 3 meters or immobilizing it on a critical hit.', 'Una bolsa de resina expansiva que se adhiere a las piernas del objetivo, reduce su Velocidad en 3 metros o lo inmoviliza con un golpe crítico.', 'Consumables', 1, '3 GP', 0, '"Alquímico","Bomba"'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.antidote_lesser', 'Antídoto (Inferior)', 'Antidote (Lesser)', 'Antídoto (menor)', 'Concede +2 de bônus de item em testes de salvaguarda contra venenos por 6 horas.', 'It grants a +2 item bonus to saves against poisons for 6 hours.', 'Concede un bonificador de objeto +2 a las salvaciones contra venenos durante 6 horas.', 'Consumables', 1, '3 GP', 0, '"Alquímico","Elixir"'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.antiplague_lesser', 'Antipeste (Inferior)', 'Antiplague (Lesser)', 'Antiplaga (menor)', 'Concede +2 de bônus de item em testes de salvaguarda contra doenças por 24 horas.', 'It grants a +2 item bonus to saves against diseases for 24 hours.', 'Concede un bonificador de objeto +2 a las salvaciones contra enfermedades durante 24 horas.', 'Consumables', 1, '3 GP', 0, '"Alquímico","Elixir"'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.smokestick_lesser', 'Bastão de Fumaça (Inferior)', 'Smokestick (Lesser)', 'Bastón de humo (menor)', 'Cria uma nuvem de fumaça espessa de 1,5m que concede Ocultação a criaturas dentro dela por 1 minuto.', 'It creates a 1.5-meter cloud of thick smoke that gives creatures inside it concealment for 1 minute.', 'Crea una nube de humo denso de 1,5 metros que proporciona ocultamiento a las criaturas dentro durante 1 minuto.', 'Consumables', 1, '3 GP', 0, '"Alquímico"'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.sunrod', 'Bastão Solar', 'Sunrod', 'Bastón solar', 'Bastão alquímico que brilha com luz solar viva de 6m por 6 horas após ser quebrado.', 'An alchemical rod that shines with sunlight in a 6-meter radius for 6 hours after being broken.', 'Una vara alquímica que brilla con luz solar en un radio de 6 metros durante 6 horas al romperse.', 'Consumables', 1, '3 GP', 0, '"Alquímico","Luz"'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.tindertwig', 'Graveto de Ignição', 'Tindertwig', 'Ramita yesquera', 'Fósforo alquímico de ignição instantânea que acende tochas em 1 única ação.', 'An alchemical match that ignites instantly and lights torches with a single action.', 'Una cerilla alquímica de ignición instantánea que enciende antorchas con una sola acción.', 'Consumables', 1, '2 SP', 0, '"Alquímico"'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.1_weapon_potency_rune', 'Runa de Potência de Arma +1', '+1 Weapon Potency Rune', 'Runa de potencia de arma +1', 'Runa fundamental mágica que concede +1 de bônus de item em jogadas de ataque com a arma gravada.', 'A fundamental magic rune granting a +1 item bonus to attack rolls with the etched weapon.', 'Una runa mágica fundamental que concede un bonificador de objeto +1 a las tiradas de ataque con el arma grabada.', 'Runes', 2, '35 GP', 0, '"Mágico","Runa"'::text[], 'common', 'remaster', 'Guia do Mestre (GM Core)', 242, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.2_weapon_potency_rune', 'Runa de Potência de Arma +2', '+2 Weapon Potency Rune', 'Runa de potencia de arma +2', 'Runa fundamental mágica que concede +2 de bônus de item em jogadas de ataque com a arma gravada.', 'A fundamental magic rune granting a +2 item bonus to attack rolls with the etched weapon.', 'Una runa mágica fundamental que concede un bonificador de objeto +2 a las tiradas de ataque con el arma grabada.', 'Runes', 10, '935 GP', 0, '"Mágico","Runa"'::text[], 'common', 'remaster', 'Guia do Mestre (GM Core)', 242, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.3_weapon_potency_rune', 'Runa de Potência de Arma +3', '+3 Weapon Potency Rune', 'Runa de potencia de arma +3', 'Runa fundamental mágica que concede +3 de bônus de item em jogadas de ataque com a arma gravada.', 'A fundamental magic rune granting a +3 item bonus to attack rolls with the etched weapon.', 'Una runa mágica fundamental que concede un bonificador de objeto +3 a las tiradas de ataque con el arma grabada.', 'Runes', 16, '8935 GP', 0, '"Mágico","Runa"'::text[], 'common', 'remaster', 'Guia do Mestre (GM Core)', 242, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.striking_rune', 'Runa Impactante', 'Striking Rune', 'Runa impactante', 'Runa fundamental que adiciona 1 dado extra de dano da arma ao acertar (2 dados no total).', 'A fundamental rune that adds 1 extra weapon damage die on a hit (2 dice total).', 'Una runa fundamental que añade 1 dado de daño adicional del arma al impactar (2 dados en total).', 'Runes', 4, '65 GP', 0, '"Mágico","Runa"'::text[], 'common', 'remaster', 'Guia do Mestre (GM Core)', 243, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.greater_striking_rune', 'Runa Impactante Maior', 'Greater Striking Rune', 'Runa impactante mayor', 'Runa fundamental que adiciona 2 dados extras de dano da arma ao acertar (3 dados no total).', 'A fundamental rune that adds 2 extra weapon damage dice on a hit (3 dice total).', 'Una runa fundamental que añade 2 dados de daño adicionales del arma al impactar (3 dados en total).', 'Runes', 12, '1065 GP', 0, '"Mágico","Runa"'::text[], 'common', 'remaster', 'Guia do Mestre (GM Core)', 243, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.major_striking_rune', 'Runa Impactante Superior', 'Major Striking Rune', 'Runa impactante mayor superior', 'Runa fundamental lendária que adiciona 3 dados extras de dano da arma ao acertar (4 dados no total).', 'A legendary fundamental rune that adds 3 extra weapon damage dice on a hit (4 dice total).', 'Una runa fundamental legendaria que añade 3 dados de daño adicionales del arma al impactar (4 dados en total).', 'Runes', 19, '31065 GP', 0, '"Mágico","Runa"'::text[], 'common', 'remaster', 'Guia do Mestre (GM Core)', 243, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.1_armor_potency_rune', 'Runa de Potência de Armadura +1', '+1 Armor Potency Rune', 'Runa de potencia de armadura +1', 'Runa fundamental que concede +1 de bônus de item na CA da armadura ou traje de explorador.', 'A fundamental rune granting a +1 item bonus to the armor or explorer''s clothing AC.', 'Una runa fundamental que concede un bonificador de objeto +1 a la CA de la armadura o la ropa de explorador.', 'Runes', 5, '160 GP', 0, '"Mágico","Runa"'::text[], 'common', 'remaster', 'Guia do Mestre (GM Core)', 242, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.resilient_rune', 'Runa Resiliente', 'Resilient Rune', 'Runa resistente', 'Runa fundamental de armadura que concede +1 de bônus de item em todas as salvaguardas (Fortitude, Reflexos, Vontade).', 'A fundamental armor rune granting a +1 item bonus to all saves (Fortitude, Reflex, and Will).', 'Una runa fundamental de armadura que concede un bonificador de objeto +1 a todas las salvaciones (Fortaleza, Reflejos y Voluntad).', 'Runes', 8, '340 GP', 0, '"Mágico","Runa"'::text[], 'common', 'remaster', 'Guia do Mestre (GM Core)', 243, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.flaming_property_rune', 'Runa de Propriedade Flamejante', 'Flaming Property Rune', 'Runa de propiedad flamígera', 'Adiciona 1d6 de dano de fogo adicional e 1d10 de dano contínuo de fogo no acerto crítico.', 'It adds 1d6 additional fire damage and 1d10 persistent fire damage on a critical hit.', 'Añade 1d6 de daño de fuego adicional y 1d10 de daño de fuego persistente con un golpe crítico.', 'Runes', 8, '500 GP', 0, '"Mágico","Fogo","Runa"'::text[], 'common', 'remaster', 'Guia do Mestre (GM Core)', 244, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.frost_property_rune', 'Runa de Propriedade Gélida', 'Frost Property Rune', 'Runa de propiedad gélida', 'Adiciona 1d6 de dano de frio adicional e deixa o alvo Lento 1 no acerto crítico.', 'It adds 1d6 additional cold damage and makes the target Slowed 1 on a critical hit.', 'Añade 1d6 de daño de frío adicional y deja al objetivo ralentizado 1 con un golpe crítico.', 'Runes', 8, '500 GP', 0, '"Mágico","Frio","Runa"'::text[], 'common', 'remaster', 'Guia do Mestre (GM Core)', 244, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.shocking_property_rune', 'Runa de Propriedade Chocante', 'Shocking Property Rune', 'Runa de propiedad impactante', 'Adiciona 1d6 de dano elétrico adicional e propaga 1d4 de dano elétrico em criaturas adjacentes no crítico.', 'It adds 1d6 additional electricity damage and deals 1d4 electricity damage to adjacent creatures on a critical hit.', 'Añade 1d6 de daño eléctrico adicional y causa 1d4 de daño eléctrico a criaturas adyacentes con un golpe crítico.', 'Runes', 8, '500 GP', 0, '"Mágico","Eletricidade","Runa"'::text[], 'common', 'remaster', 'Guia do Mestre (GM Core)', 245, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.returning_property_rune', 'Runa de Propriedade Retornante', 'Returning Property Rune', 'Runa de propiedad retornante', 'Quando você arremessa a arma gravada, ela retorna imediatamente à sua mão logo após o ataque.', 'When you throw the etched weapon, it immediately returns to your hand after the attack.', 'Cuando lanzas el arma grabada, vuelve inmediatamente a tu mano tras el ataque.', 'Runes', 3, '55 GP', 0, '"Mágico","Runa"'::text[], 'common', 'remaster', 'Guia do Mestre (GM Core)', 245, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.ghost_touch_property_rune', 'Runa de Propriedade Toque Fantasma', 'Ghost Touch Property Rune', 'Runa de propiedad toque fantasmal', 'A arma atinge criaturas incorpóreas com eficácia total, ignorando resistências a dano físico.', 'The weapon affects incorporeal creatures with full effect, ignoring physical damage resistances.', 'El arma afecta plenamente a las criaturas incorpóreas e ignora sus resistencias al daño físico.', 'Runes', 4, '75 GP', 0, '"Mágico","Runa"'::text[], 'common', 'remaster', 'Guia do Mestre (GM Core)', 244, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
