  ('item.rage_elements.metal.zuhras_gloves', 'Luvas de Zuhra', 'Zuhra''s Gloves', 'Guantes de Zuhra', 'Luvas investidas que protegem contra desarme e canalizam ataques ou muralhas de metal.', 'Rage of Elements metal item: Zuhra''s Gloves. Full mechanical text pending review.', 'Objeto de metal de Rage of Elements: Guantes de Zuhra. El texto mecánico completo queda pendiente de revisión.', 'magical', 13, '0 PO', 0, '{}'::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 148, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.smoke_ball', 'Bola de Fumaça', 'Smoke Ball', 'Bola de humo', 'Item alquímico que libera uma nuvem de fumaça para ocultar uma área.', 'An alchemical item that releases a cloud of smoke to conceal an area.', 'Objeto alquímico que libera una nube de humo para ocultar un área.', 'compendio', 1, '[object Object]', 0, '"Alquímico","Consumível"'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 295, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.horned_arrow', 'Flecha de Galhada', 'Horned Arrow', 'Flecha de astas', 'Ao atingir, galhadas luminosas prendem o alvo em uma superfície após um salvamento de Reflexos.', 'On a hit, luminous antlers pin the target to a surface after a Reflex save.', 'Al impactar, unas astas luminosas fijan al objetivo a una superficie tras una salvación de Reflejos.', 'compendio', 2, '[object Object]', 0, '"Consumível","Mágico","Munição"'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 301, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.storm_arrow', 'Flecha de Tempestade', 'Storm Arrow', 'Flecha de tormenta', 'Ao atingir, causa 3d12 de dano de eletricidade e exige um salvamento de Reflexos.', 'On a hit, it deals 3d12 electricity damage and requires a Reflex save.', 'Al impactar, causa 3d12 de daño eléctrico y requiere una salvación de Reflejos.', 'compendio', 9, '[object Object]', 0, '"Consumível","Mágico","Munição"'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 301, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.viper_arrow', 'Flecha de Víbora', 'Viper Arrow', 'Flecha de víbora', 'Ao atingir, transforma-se em uma víbora convocada que afeta o alvo com seu veneno.', 'On a hit, it transforms into a summoned viper whose poison affects the target.', 'Al impactar, se transforma en una víbora convocada cuyo veneno afecta al objetivo.', 'compendio', 4, '[object Object]', 0, '"Consumível","Mágico","Munição"'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 301, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.sleep_arrow', 'Flecha do Sono', 'Sleep Arrow', 'Flecha del sueño', 'Não causa dano; uma criatura viva atingida faz um salvamento de Vontade ou fica letárgica e lenta.', 'It deals no damage; a living creature hit must make a Will save or become lethargic and slowed.', 'No causa daño; una criatura viva impactada debe hacer una salvación de Voluntad o queda aletargada y ralentizada.', 'compendio', 3, '[object Object]', 0, '"Consumível","Mágico","Munição"'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 301, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.frightening_ammunition', 'Munição Aterrorizante', 'Frightening Ammunition', 'Munición aterrorizante', 'Ao ferir, enche a mente do alvo com visões terríveis e pode deixá-lo assustado.', 'On a hit, it fills the target''s mind with terrifying visions and can make it frightened.', 'Al herir, llena la mente del objetivo de visiones aterradoras y puede asustarlo.', 'compendio', 6, '[object Object]', 0, '"Consumível","Mágico","Munição"'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 302, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.freezing_ammunition', 'Munição Congelante', 'Freezing Ammunition', 'Munición congelante', 'Ao atingir, exige um salvamento de Fortitude ou deixa o alvo lento pelo frio intenso.', 'On a hit, it requires a Fortitude save or slows the target from intense cold.', 'Al impactar, requiere una salvación de Fortaleza o ralentiza al objetivo por el frío intenso.', 'compendio', 5, '[object Object]', 0, '"Consumível","Mágico","Munição"'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 302, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.corrosive_ammunition', 'Munição Corrosiva', 'Corrosive Ammunition', 'Munición corrosiva', 'Ao atingir, causa 1d8 de dano de ácido persistente que ignora a Dureza da armadura.', 'On a hit, it deals 1d8 persistent acid damage that ignores armor Hardness.', 'Al impactar, causa 1d8 de daño de ácido persistente que ignora la Dureza de la armadura.', 'compendio', 7, '[object Object]', 0, '"Consumível","Mágico","Munição"'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 302, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.disintegration_bolt', 'Virote de Desintegração', 'Disintegration Bolt', 'Virote de desintegración', 'Ao atingir, afeta o alvo como a magia desintegrar após um salvamento de Fortitude.', 'On a hit, it affects the target like the disintegrate spell after a Fortitude save.', 'Al impactar, afecta al objetivo como el conjuro desintegrar tras una salvación de Fortaleza.', 'compendio', 15, '[object Object]', 0, '"Consumível","Mágico","Munição"'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 302, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.urgent_escape_potion', 'Poção de Fuga Urgente', 'Urgent Escape Potion', 'Poción de fuga urgente', 'Ao beber, fica fugindo por 1 minuto, recebe +12 metros nas Velocidades e Anda imediatamente.', 'When consumed, you flee for 1 minute, gain a +12-meter status bonus to Speeds, and immediately Stride.', 'Al beberla, huyes durante 1 minuto, obtienes +12 metros a las Velocidades y Avanzas inmediatamente.', 'compendio', 1, '[object Object]', 0, '"Consumível","Mágico","Poção"'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 304, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.retaliation_potion_minimum', 'Poção da Retaliação Mínima', 'Retaliation Potion (Minimum)', 'Poción de represalia mínima', 'Por 1 minuto, uma aura causa 1 de dano de ácido, eletricidade, fogo ou frio a quem tocar você.', 'For 1 minute, an aura deals 1 acid, electricity, fire, or cold damage to creatures that touch you.', 'Durante 1 minuto, una aura causa 1 de daño de ácido, electricidad, fuego o frío a quienes te toquen.', 'compendio', 1, '[object Object]', 0, '"Consumível","Mágico","Poção"'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 304, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.ration_tonic', 'Tônico de Ração', 'Ration Tonic', 'Tónico de ración', 'Ao beber, você fica magicamente alimentado com o equivalente a um dia de comida e água.', 'When consumed, you become magically nourished with the equivalent of one day''s food and water.', 'Al beberlo, quedas alimentado mágicamente con el equivalente a un día de comida y agua.', 'compendio', 1, '[object Object]', 0, '"Consumível","Mágico","Poção"'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 304, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.snake_oil', 'Óleo de Cobra', 'Snake Oil', 'Aceite de serpiente', 'Disfarça temporariamente o cheiro e a aparência de um objeto para dificultar sua identificação.', 'Temporarily masks an object''s smell and appearance to make identification harder.', 'Oculta temporalmente el olor y la apariencia de un objeto para dificultar su identificación.', 'compendio', 1, '[object Object]', 0, '"Alquímico","Consumível"'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 295, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.ghost_ink', 'Tinta Fantasma', 'Ghost Ink', 'Tinta fantasmal', 'Tinta alquímica que fica invisível até ser revelada por um método apropriado.', 'Alchemical ink that remains invisible until revealed by an appropriate method.', 'Tinta alquímica que permanece invisible hasta que un método apropiado la revela.', 'compendio', 1, '[object Object]', 0, '"Alquímico","Consumível"'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 296, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.mystic_shield_paste', 'Pasta de Escudo Místico', 'Mystic Armor Paste', 'Pasta de escudo místico', 'Reforça temporariamente uma armadura ou escudo contra um tipo de energia escolhido.', 'Temporarily reinforces armor or a shield against a chosen energy type.', 'Refuerza temporalmente una armadura o escudo contra un tipo de energía elegido.', 'compendio', 2, '[object Object]', 0, '"Alquímico","Consumível"'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 303, '{"hands":null,"usage":null,"effects":[],"needs_review":false}'::jsonb),
